<template><ElConfigProvider namespace="kel"><section class="native-schedule"><header><div><h3>项目调度</h3><small>Kestra Cron · Revision {{revision||'未保存'}}</small></div><KsButton size="small" disabled title="设备Webhook/事件尚无受控Job Adapter；不会绕过项目授权、预检和审批">设备事件未启用</KsButton><span :class="['state',{enabled:form.enabled}]">{{form.enabled?'ENABLED':'DISABLED'}}</span><KsButton size="small" :disabled="busy" @click="emit('refresh')">刷新状态</KsButton><KsButton type="primary" size="small" :loading="busy" :disabled="!canEdit||!form.cron||!selected.length||(!form.command&&!(form.useSteps&&steps.length))" @click="emit('save')">保存调度</KsButton></header><p v-if="error" class="error">{{error}}</p><div class="runtime"><div><small>上次实际触发</small><b>{{date(runtime?.runtime?.[0]?.lastTriggeredDate)}}</b></div><div><small>下次引擎检查</small><b>{{date(runtime?.runtime?.[0]?.nextEvaluationDate)}}</b></div><div><small>运行态</small><b>{{runtime?.runtime_error?'UNKNOWN · 引擎不可用':runtime?.runtime?.[0]?.locked?'LOCKED':runtime?.runtime?.[0]?(runtime.runtime[0].disabled||runtime.runtime[0].sourceDisabled?'DISABLED':'ENABLED'):'UNKNOWN · 尚无运行态'}}</b></div></div><div class="schedule-fields"><label>Cron<input :value="form.cron" :disabled="!canEdit" placeholder="0 */6 * * *" @input="patch('cron',value($event))"/></label><label>Timezone<input :value="form.zone" :disabled="!canEdit" @input="patch('zone',value($event))"/></label><label>执行通道<select :value="form.policy" :disabled="!canEdit" @change="patch('policy',value($event))"><option value="agent_preferred">Agent Preferred</option><option value="agent_only">Agent Only</option><option value="ssh_only">SSH Only</option></select></label><label class="toggle"><input type="checkbox" :checked="form.enabled" :disabled="!canEdit" @change="patch('enabled',($event.target as HTMLInputElement).checked)"/>启用未来调度</label></div><details class="targets"><summary>冻结目标 · {{selected.length}} 台设备 <span>展开选择 CMDB 资产</span></summary><div class="target-rows"><label v-for="target in targets" :key="target.id"><input type="checkbox" :checked="selected.includes(target.id)" :disabled="!canEdit" @change="emit('select',($event.target as HTMLInputElement).checked?[...selected,target.id]:selected.filter(id=>id!==target.id))"/><b>{{target.name}}</b><code>{{target.id}}</code></label></div></details><div class="schedule-fields parameters"><label>脚本类型<select :value="form.kind" :disabled="!canEdit" @change="patch('kind',value($event))"><option value="bash">Bash</option><option value="python">Python</option><option value="command">Command</option></select></label><label>Timeout · s<input type="number" min="1" max="3600" :value="form.timeout" :disabled="!canEdit" @input="patch('timeout',Number(value($event)))"/></label><label>目标并发<input type="number" min="1" max="64" :value="form.concurrency" :disabled="!canEdit" @input="patch('concurrency',Number(value($event)))"/></label><label class="toggle"><input type="checkbox" :checked="form.useSteps" :disabled="!canEdit" @change="patch('useSteps',($event.target as HTMLInputElement).checked)"/>多步骤 · {{steps.length}}</label></div><div v-if="form.useSteps" class="step-plan"><code>{{steps.map(s=>s.id).join(' → ')||'计划中尚无步骤'}}</code><KsButton size="small" :disabled="!canEdit" @click="emit('reloadSteps')">从当前 Flow 更新步骤</KsButton></div><template v-else><div class="script-header"><b>执行脚本</b><KsButton size="small" :disabled="!canEdit" @click="emit('reloadScript')">使用 Flow 脚本</KsButton></div><NativeCodeEditor :source="form.command" :readOnly="!canEdit" path="schedule-script" :language="form.kind==='python'?'python':'shell'" :theme="theme" @change="v=>patch('command',v)" @save="canEdit&&emit('save')"/></template><small class="note">每次触发重新校验授权、目标版本与通道；高危操作仍需独立批准。修改 Flow 后须重新保存调度。</small><details class="history"><summary>触发消费记录 · {{runtime?.history?.length||0}} <span>最近50条，不等同设备执行成功</span></summary><div v-for="fire in runtime?.history||[]" :key="fire.engine_execution_id" class="fire"><time>{{date(fire.created_at)}}</time><b>{{fire.state}}</b><button v-if="fire.execution_id" class="link" @click="emit('navigate','/flows/executions/'+fire.execution_id)">{{fire.execution_id.slice(0,12)}} →</button><span>{{fire.error_code||'—'}}</span></div><p v-if="!runtime?.history?.length">暂无已消费触发记录</p></details></section></ElConfigProvider></template>
<script setup lang="ts">
import {ElConfigProvider} from 'element-plus';import KsButton from '../../vendor/kestra/design-system/components/Basic/KsButton/KsButton.vue';import NativeCodeEditor from './NativeCodeEditor.vue';defineProps<{form:any;revision:number;selected:string[];targets:any[];steps:any[];runtime:any;canEdit:boolean;busy:boolean;error:string;theme:'light'|'dark'}>();const emit=defineEmits(['patch','select','save','refresh','reloadSteps','reloadScript','navigate']);const patch=(key:string,v:unknown)=>emit('patch',key,v),value=(e:Event)=>(e.target as HTMLInputElement).value,date=(v:any)=>v?new Date(v).toLocaleString():'未知 / 未上报';
</script>
<style scoped>.native-schedule{font:12px var(--ks-font-family-sans);color:var(--ks-text-primary);background:var(--ks-bg-surface);padding:18px 20px}header{display:flex;align-items:center;gap:12px}header>div{margin-right:auto}h3{font-size:17px;margin:0 0 5px}small{font-size:10px;color:var(--ks-text-secondary)}.state{font-size:10px;color:var(--ks-text-secondary)}.state.enabled{color:#309e7c}.runtime{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;border-block:1px solid var(--ks-border-default);padding:12px 0;margin:16px 0}.runtime small,.runtime b{display:block}.runtime b{font-size:11px;margin-top:5px;font-weight:500}.schedule-fields{display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:16px;align-items:end}label{font-size:11px;color:var(--ks-text-secondary)}input:not([type=checkbox]),select{display:block;width:100%;padding:7px 9px;margin-top:5px;border:1px solid var(--ks-border-default);border-radius:4px;background:var(--ks-bg-input);color:var(--ks-text-primary);font-size:11px}.toggle{display:flex;align-items:center;gap:8px;min-height:32px}.targets,.history{border-block:1px solid var(--ks-border-default);padding:12px 0;margin:15px 0}summary{cursor:pointer;font-size:11px}summary span{color:var(--ks-text-secondary);font-size:10px;margin-left:14px}.target-rows{max-height:180px;overflow:auto;padding-top:12px;display:grid;grid-template-columns:repeat(2,1fr);gap:9px}.target-rows label{display:flex;gap:8px;align-items:center}.target-rows code{font-size:9px}.script-header,.step-plan{display:flex;align-items:center;justify-content:space-between;margin:14px 0;font-size:11px}.native-schedule :deep(.native-code-editor){height:230px;min-height:230px;border:1px solid var(--ks-border-default)}.note{display:block;margin-top:12px;line-height:1.5}.fire{display:flex;align-items:center;gap:16px;padding:10px 0;font-size:10px;border-bottom:1px solid var(--ks-border-default)}.history p{font-size:11px;color:var(--ks-text-secondary)}.link{color:var(--ks-text-link)}.error{color:#df7490;font-size:11px}.history{margin-bottom:0}@media(max-width:1000px){.schedule-fields{grid-template-columns:repeat(2,1fr)}}</style>
